SELECT (DATE_TRUNC('DAY', "GRANTED_AT")) AS "TIME_BUCKET", COUNT(*) AS "SEC_NEW_GRANTS" FROM (SELECT g."ROLE" AS ROLE_NAME, g."GRANTED_TO" AS GRANTED_TO, g."GRANTEE_NAME" AS GRANTEE_NAME, g."GRANTED_BY" AS GRANTED_BY, (TRY_TO_TIMESTAMP_NTZ(g."CREATED_ON")) AS GRANTED_AT, (TRY_TO_TIMESTAMP_NTZ(g."DELETED_ON")) AS REVOKED_AT, COALESCE(u."DISABLED", FALSE) AS GRANTEE_DISABLED, u."TYPE" AS GRANTEE_TYPE, (TRY_TO_TIMESTAMP_NTZ(u."LAST_SUCCESS_LOGIN")) AS GRANTEE_LAST_LOGIN_AT FROM grants_to_users AS g LEFT JOIN users AS u ON u."NAME" = g."GRANTEE_NAME") AS base GROUP BY (DATE_TRUNC('DAY', "GRANTED_AT")) ORDER BY "SEC_NEW_GRANTS" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
